from lib import *
L = lambda *a, **k: lesson(21, "A0", *a, **k)
V = "verb"
A = "adjective"
L(1, "Що? Хто? Де?", "Ставити питання про річ, людину й місце.",
 "Питальне слово стоїть першим. What — про річ, who — про людину, where — про місце. З дією далі йде do: What do you want? Where do you live? З am / is / are do не потрібне: Who is she?",
 [W("thing", "/θɪŋ/", "noun", "річ", "What is this thing?", "Що це за річ?"),
  W("person", "/ˈpɜːsn/", "noun", "людина, особа", "She's a nice person.", "Вона приємна людина."),
  W("place", "/pleɪs/", "noun", "місце", "It's a beautiful place.", "Це гарне місце."),
  W("something", "/ˈsʌmθɪŋ/", "pronoun", "щось", "I want something to eat.", "Я хочу щось поїсти."),
  W("about", "/əˈbaʊt/", "preposition", "про", "What is the film about?", "Про що цей фільм?")],
 [li("How often do you cook?", "Повторимо. Ви готуєте щодня. Що відповісти?", ["Every day.", "Every days.", "Often day."], "Every day."),
  mt([("what", "що"), ("who", "хто"), ("where", "де"), ("when", "коли"), ("why", "чому")], "П'ять головних питальних слів."),
  mt([("thing", "річ"), ("person", "людина"), ("place", "місце"), ("something", "щось"), ("about", "про")], "Одна людина — person, багато — people."),
  mcu("Яким словом питають про людину?", ["who", "what", "where"], "Who — хто."),
  mcu("Яким словом питають про місце?", ["where", "when", "who"], "Where — де."),
  fb("___ do you live? — In Warsaw.", ["Where", "What", "Who"], "Відповідь про місце — питання Where."),
  fb("___ is that woman? — She's my boss.", ["Who", "What", "Where"], "Про людину — Who."),
  fb("What ___ you want for lunch?", ["do", "are", "is"], "З дією want — do."),
  liu("What is the book about?", "Прослухайте. Що питає людина?", ["Про що книжка", "Чия це книжка", "Де книжка"], "About — про."),
  bs("Що ви хочете?", ["What", "do", "you", "want"], ["are", "who"], "What do you want?"),
  tr("Де ви працюєте?", ["Where do you work"], "Where do you work?"),
  li("Who is that person?", "Це ваш сусід. Що відповісти?", ["He's my neighbour.", "It's a neighbour place.", "He's something."], "He's my neighbour.")])
L(2, "Як довго? Як далеко?", "Спитати про тривалість і відстань.",
 "How разом з іншим словом дає нове питання: How long…? — «Як довго? Скільки триває?». How far…? — «Як далеко?». Far — далеко, near — близько. About ще означає «приблизно»: about ten minutes.",
 [W("how long", "/ˌhaʊ ˈlɒŋ/", "phrase", "як довго, скільки часу", "How long is the film?", "Скільки триває фільм?"),
  W("how far", "/ˌhaʊ ˈfɑː/", "phrase", "як далеко", "How far is the station?", "Як далеко вокзал?"),
  W("far", "/fɑː/", A, "далекий, далеко", "It isn't far.", "Це недалеко."),
  W("near", "/nɪə/", A, "близький, близько", "It's very near.", "Це дуже близько."),
  W("kilometre", "/ˈkɪləmiːtə/", "noun", "кілометр", "Two kilometres.", "Два кілометри.")],
 [fb("___ do you work? — In a bank.", ["Where", "Who", "When"], "Where — де.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("how long", "як довго"), ("how far", "як далеко"), ("how often", "як часто"), ("how much", "скільки коштує"), ("how many", "скільки штук")], "How + слово = нове питання."),
  mt([("far", "далеко"), ("near", "близько"), ("kilometre", "кілометр"), ("minute", "хвилина")], "Far і near — протилежні слова."),
  liu("How far is the hotel?", "Прослухайте. Що питає людина?", ["Як далеко готель", "Скільки коштує готель", "Де готель"], "How far — як далеко."),
  liu("It's about ten minutes on foot.", "Прослухайте. Скільки йти?", ["Приблизно 10 хвилин пішки", "Рівно 10 хвилин машиною", "Приблизно 10 кілометрів"], "About ten minutes — приблизно десять хвилин."),
  fb("How ___ is the film? — Two hours.", ["long", "far", "often"], "Про тривалість — How long."),
  fb("How ___ is the station? — Two kilometres.", ["far", "long", "many"], "Про відстань — How far."),
  mc("Як сказати «Це недалеко»?", ["It isn't far.", "It isn't near.", "It doesn't far."], "It isn't far."),
  mcu("Що означає about five kilometres?", ["Приблизно 5 кілометрів", "Рівно 5 кілометрів", "Про 5 кілометрів"], "About — приблизно."),
  bs("Як далеко вокзал?", ["How", "far", "is", "the", "station"], ["long", "does"], "How far is the station?"),
  tr("Скільки триває фільм?", ["How long is the film"], "How long is the film?"),
  li("How far is your office?", "Офіс дуже близько, п'ять хвилин пішки. Що відповісти?", ["It's very near. Five minutes on foot.", "It's very far. Five minutes on foot.", "It's five kilometres long."], "It's very near.")])
L(3, "Are you чи Do you?", "Правильно вибрати між are і do в питанні.",
 "Головне правило питань. Якщо в реченні стан або опис (хто я, який, де) — питаємо з am / is / are: Are you tired? Is he at home? Якщо дія — з do / does: Do you work? Does she drive? Разом їх не ставлять.",
 [W("true", "/truː/", A, "правдивий", "It's true.", "Це правда."),
  W("false", "/fɔːls/", A, "хибний", "It's false.", "Це неправда."),
  W("correct", "/kəˈrekt/", A, "правильний", "The correct answer.", "Правильна відповідь."),
  W("mistake", "/mɪˈsteɪk/", "noun", "помилка", "It's a mistake.", "Це помилка.")],
 [fb("How ___ is the station? — One kilometre.", ["far", "long", "much"], "How far.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("true", "правдивий"), ("false", "хибний"), ("correct", "правильний"), ("mistake", "помилка")], "Слова про правильне й неправильне."),
  fb("___ you tired?", ["Are", "Do", "Does"], "Tired — стан, тому Are."),
  fb("___ you work on Sunday?", ["Do", "Are", "Is"], "Work — дія, тому Do."),
  fb("___ she at home?", ["Is", "Does", "Do"], "At home — де вона: Is."),
  fb("___ he speak English?", ["Does", "Is", "Are"], "Speak — дія, з he — Does."),
  mc("Яке питання правильне?", ["Do you like coffee?", "Are you like coffee?", "Do you are like coffee?"], "Like — дія: Do you like…?"),
  mc("Яке питання правильне?", ["Is your brother a doctor?", "Does your brother a doctor?", "Do your brother is a doctor?"], "Хто він — Is."),
  mc("Яке питання правильне?", ["Where does she live?", "Where is she live?", "Where she lives?"], "Live — дія: Where does she live?"),
  liu("Are you ready?", "Прослухайте. Як відповісти коротко «так»?", ["Yes, I am.", "Yes, I do.", "Yes, I ready."], "На Are you…? — Yes, I am."),
  liu("Do you understand?", "Прослухайте. Як відповісти коротко «ні»?", ["No, I don't.", "No, I'm not.", "No, I understand not."], "На Do you…? — No, I don't."),
  bs("Він працює тут?", ["Does", "he", "work", "here"], ["is", "works"], "Does he work here?")])
L(4, "Не знаю, мабуть", "Відповісти, коли ви не впевнені.",
 "Не завжди можна сказати yes або no. Корисні відповіді: I think so — «думаю, що так». I don't think so — «думаю, що ні». I'm not sure — «я не впевнений». Probably — «мабуть». It depends — «залежить».",
 [W("I think so", "/aɪ ˈθɪŋk səʊ/", "phrase", "думаю, що так", "Is it open? — I think so.", "Відчинено? — Думаю, що так."),
  W("I don't think so", "/aɪ ˌdəʊnt ˈθɪŋk səʊ/", "phrase", "думаю, що ні", "Is it far? — I don't think so.", "Це далеко? — Думаю, що ні."),
  W("I'm not sure", "/aɪm ˌnɒt ˈʃɔː/", "phrase", "я не впевнений", "I'm not sure.", "Я не впевнений."),
  W("probably", "/ˈprɒbəbli/", "adverb", "мабуть", "Probably tomorrow.", "Мабуть, завтра."),
  W("it depends", "/ɪt dɪˈpendz/", "phrase", "залежить", "It depends.", "Залежить.")],
 [fb("___ you speak Polish?", ["Do", "Are", "Is"], "Speak — дія: Do.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("I think so", "думаю, що так"), ("I don't think so", "думаю, що ні"), ("I'm not sure", "я не впевнений"), ("probably", "мабуть"), ("it depends", "залежить")], "Відповіді між «так» і «ні»."),
  liu("Is the bank open today? — I think so.", "Прослухайте. Що відповіла людина?", ["Думає, що відчинено", "Думає, що зачинено", "Не знає"], "I think so — думаю, що так."),
  liu("I'm not sure.", "Прослухайте. Що каже людина?", ["Вона не впевнена", "Вона впевнена", "Вона не згодна"], "I'm not sure."),
  mc("Вас питають: Is it far? Ви думаєте, що ні. Що відповісти?", ["I don't think so.", "I think not so.", "I don't think it."], "I don't think so."),
  mc("Вас питають: Do you like parties? Залежить від вечірки. Що відповісти?", ["It depends.", "It depend.", "I depends."], "It depends."),
  fb("Is he at home? — ___. He's usually at home in the evening.", ["Probably", "Never", "False"], "Probably — мабуть."),
  fb("Is this the right bus? — I'm not ___.", ["sure", "think", "depends"], "I'm not sure."),
  mcu("Яка відповідь найбільш упевнена?", ["Yes, of course.", "I think so.", "Probably."], "Of course — звичайно."),
  bs("Я не впевнений.", ["I'm", "not", "sure"], ["don't", "so"], "I'm not sure."),
  tr("Думаю, що так.", ["I think so"], "I think so."),
  li("Is the supermarket open on Sunday?", "Ви не знаєте напевно. Що відповісти?", ["I'm not sure. Probably.", "I'm not think. Probably.", "No, I don't sure."], "I'm not sure. Probably.")])
L(5, "Перепрошую, де тут туалет?", "Ввічливо звернутися до незнайомої людини й знайти потрібне в будівлі.",
 "До незнайомих звертаються з Excuse me. Найввічливіше прохання — Could you…?: Could you help me, please? Це м'якше, ніж Can you…? На табличках: Entrance — вхід, Exit — вихід, Toilets — туалети, Information — довідка.",
 [W("could", "/kʊd/", V, "могли б (ввічливо)", "Could you help me?", "Чи не могли б ви мені допомогти?"),
  W("toilet", "/ˈtɔɪlət/", "noun", "туалет", "Where are the toilets?", "Де туалети?"),
  W("exit", "/ˈeksɪt/", "noun", "вихід", "Where is the exit?", "Де вихід?"),
  W("entrance", "/ˈentrəns/", "noun", "вхід", "The entrance is over there.", "Вхід он там."),
  W("information", "/ˌɪnfəˈmeɪʃn/", "noun", "інформація, довідка", "Where is information?", "Де довідка?")],
 [li("Is it far?", "Повторимо. Ви думаєте, що ні. Що відповісти?", ["I don't think so.", "I think not so.", "I'm not think."], "I don't think so."),
  mt([("toilet", "туалет"), ("exit", "вихід"), ("entrance", "вхід"), ("information", "довідка")], "Написи в аеропорту, на вокзалі, у торговому центрі."),
  liu("Excuse me, where are the toilets?", "Прослухайте. Що шукає людина?", ["Туалети", "Вихід", "Довідку"], "The toilets."),
  liu("Could you repeat that, please?", "Прослухайте. Про що просить людина?", ["Повторити", "Допомогти", "Показати"], "Repeat — повторити."),
  mcu("Яке прохання найввічливіше?", ["Could you help me, please?", "Can you help me?", "Help me."], "Could you…, please? — найм'якше."),
  fb("Excuse me, ___ you tell me the time, please?", ["could", "do", "are"], "Could you tell me…?"),
  fb("Where is the ___? I want to go out.", ["exit", "entrance", "toilet"], "Вийти — через exit."),
  mc("Як правильно почати питання до незнайомої людини?", ["Excuse me, …", "Sorry me, …", "Hello you, …"], "Excuse me."),
  mcu("Що означає напис Entrance?", ["Вхід", "Вихід", "Довідка"], "Entrance — вхід."),
  bs("Де вихід?", ["Where", "is", "the", "exit"], ["are", "entrance"], "Where is the exit?"),
  tr("Чи не могли б ви мені допомогти?", ["Could you help me", "Could you help me, please"], "Could you help me?"),
  li("Excuse me, could you help me?", "До вас звернулися по допомогу. Ви згодні. Що відповісти?", ["Yes, of course.", "Yes, I could of.", "No problem not."], "Yes, of course.")])
L(6, "Повторення: питання й відповіді", "Упевнено ставити питання й відповідати на них.",
 "Нових слів немає. Повторюємо питальні слова, How long і How far, вибір між are і do, відповіді I think so та I'm not sure, ввічливе Could you…?",
 [],
 [fb("___ does the film start? — At eight.", ["When", "Where", "Who"], "Відповідь про час — When."),
  fb("___ you from Poland?", ["Are", "Do", "Does"], "Звідки ви — Are."),
  fb("___ your sister live in Kyiv?", ["Does", "Is", "Do"], "Live — дія, sister — she: Does."),
  bs("Як далеко готель?", ["How", "far", "is", "the", "hotel"], ["long", "do"], "How far is the hotel?"),
  tr("Про що цей фільм?", ["What is the film about", "What is this film about", "What's the film about"], "What is the film about?"),
  liu("How long do you work every day? — About eight hours.", "Прослухайте. Скільки людина працює?", ["Приблизно 8 годин", "Рівно 8 годин", "Приблизно 18 годин"], "About eight hours."),
  mc("Яке питання правильне?", ["What time do you get up?", "What time are you get up?", "What time you get up?"], "Get up — дія: do."),
  mc("Вас питають: Is the museum open on Monday? Ви не знаєте. Що відповісти?", ["I'm not sure.", "I'm not think so.", "It depend."], "I'm not sure."),
  tr("Де туалети?", ["Where are the toilets", "Where is the toilet"], "Where are the toilets?"),
  liu("Excuse me, could you tell me where the exit is?", "Прослухайте. Що шукає людина?", ["Вихід", "Вхід", "Туалет"], "The exit."),
  li("Do you like your job?", "Залежить від дня. Що відповісти?", ["It depends.", "I depend.", "It's depends."], "It depends."),
  li("Are you sure?", "Ви впевнені. Що відповісти?", ["Yes, I am.", "Yes, I do.", "Yes, I sure."], "На Are you…? — Yes, I am.")],
 review=True)
